-- MT2009_PLUS_NS_WIKI_ITEMS_V1 (Autor: Digi Rasta, nowy-system 0.33.0): the item families and upgrade
-- materials of the official PL wiki our world did not have. Generated by tools/wikinowe/gen_wikinowe_sql.py
-- from tools/wikinowe/wiki_nowe.json - do not edit. Run by apply.sh at every start; idempotent: only our own
-- rows (the same vnum and name) are deleted and written again, a row the mod made with another name stays.
SET NAMES utf8mb4;
USE world;

CREATE TEMPORARY TABLE tmp_wikinowe_names (vnum INT UNSIGNED NOT NULL PRIMARY KEY, locale_name VARCHAR(32) CHARACTER SET cp1250 NOT NULL);
DELETE p FROM world.item_proto p JOIN tmp_wikinowe_names t ON t.vnum = p.vnum AND BINARY t.locale_name = BINARY p.locale_name;
DROP TEMPORARY TABLE tmp_wikinowe_names;

ON DUPLICATE KEY UPDATE vnum0 = VALUES(vnum0), count0 = VALUES(count0), vnum1 = VALUES(vnum1), count1 = VALUES(count1), vnum2 = VALUES(vnum2), count2 = VALUES(count2), vnum3 = VALUES(vnum3), count3 = VALUES(count3), vnum4 = VALUES(vnum4), count4 = VALUES(count4), cost = VALUES(cost), src_vnum = VALUES(src_vnum), result_vnum = VALUES(result_vnum), prob = VALUES(prob);
